"""Deterministic, offline dataset builder. Never contacts a service or invents remote IDs."""
from pathlib import Path
import argparse, csv, hashlib, json, re
from datetime import date, timedelta
from catalog import *

ROOT = Path(__file__).resolve().parents[1]
PEOPLE = {x[0]: x[1] for x in EMPLOYEES}
def save(path, value):
    target = ROOT / path
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(json.dumps(value, ensure_ascii=False, indent=2)+'\n' if not isinstance(value,str) else value, encoding='utf-8')
def read(path, default):
    p=ROOT/path
    return json.loads(p.read_text(encoding='utf-8-sig')) if p.exists() else default
def jira_ref(seed):
    remote = read('jira/remote-map.json',{}).get(seed,{})
    return f"[{remote['key']}]({remote['url']})" if remote.get('key') else f"local seed `{seed}` (not published)"
def facts_for(kind, id):
    return [f for f in FACTS if id in f.get(kind,[])]
def references(ids): return ', '.join(jira_ref(i) for i in ids)

def build_issues():
    issues=[]
    for project,source in [('ATLAS',ATLAS),('BEACON',BEACON),('HARBOR',HARBOR)]:
        prefix=project.lower()
        for n,line in enumerate(source.strip().splitlines()):
            slug,typ,owner,state,priority,due,title,problem,checks=line.strip().split('|')
            checks=[s.strip() for s in checks.split(';')]
            seed=prefix+'-'+slug
            epics={'ATLAS':['identity','portal','release'],'BEACON':['pipeline','dashboards','release'],'HARBOR':['auth','webhooks','launch']}[project]
            parent=None if typ=='Epic' else prefix+'-'+epics[0 if slug in {'claims','tenant-leak','event-api','role-matrix','rbac-api','sso','audit','consent','reset','deletion','event-ingest','schema','tenant-partition','late-events','dedupe','retention','rbac','auth-integration','ownership','mapping','rotation','sdk','deactivate'} else 2 if slug in {'readiness','pilot','rehearsal','approval','business-approval','checklist','sales-pack','technical-ready'} else 1]
            issues.append(dict(seed_id=seed,project=project,summary=title,issue_type=typ,fictional_owner=owner,business_state=state,priority=priority,due_date=due,parent_seed=parent,problem=problem,acceptance_criteria=checks,release=next(p['release'] for p in PROJECTS if p['key']==project),sprint='ABL Sprint 24' if state in ['In Progress','Blocked'] else 'ABL Sprint 23' if state=='Done' else 'ABL Sprint 25',fictional_completed_date=due if state=='Done' else None))
        for slug,parent,owner,state,title in SUBTASKS[project]:
            parent_issue=next(x for x in issues if x['seed_id']==prefix+'-'+parent)
            issues.append(dict(seed_id=prefix+'-'+slug,project=project,summary=title,issue_type='Sub-task',fictional_owner=owner,business_state=state,priority='High' if state=='Blocked' else 'Medium',due_date='2026-11-13' if state=='Done' else parent_issue['due_date'],parent_seed=prefix+'-'+parent,problem='This verification step supplies acceptance evidence for '+parent_issue['summary'].lower()+'.',acceptance_criteria=[title+' using the documented test fixture','Attach observed results to the parent work item','Keep the parent gate open if any required check fails'],release=parent_issue['release'],sprint=parent_issue['sprint'],fictional_completed_date='2026-11-13' if state=='Done' else None))
    for item in issues:
        deps=[a for a,b,t in LINKS if b==item['seed_id'] and t=='Blocks']
        item['depends_on']=deps
        owner=PEOPLE[item['fictional_owner']]
        related=[f for f in FACTS if item['seed_id'] in f['issues']]
        scenario='\n\n'.join(f['answer'] for f in related)
        item['description']='\n\n'.join([
            'AsterBridge Labs fictional enterprise test dataset. Seed ID: '+item['seed_id']+'. Scenario date: '+AS_OF+'.',
            '## Business context\n'+item['problem']+'.',
            f"## Ownership and delivery\nFictional accountable owner: {owner}. Business state as of {AS_OF}: {item['business_state']}. Target due date: {item['due_date']}. Release: {item['release']}. Planning sprint: {item['sprint']}. These planning labels do not imply a native Jira sprint or version exists.",
            '## Acceptance criteria\n'+'\n'.join('- '+c+'.' for c in item['acceptance_criteria']),
            '## Dependencies\n'+(references(deps) if deps else 'No unresolved inbound blocking dependency is recorded for this work item.'),
            '## Decision and history\n'+(scenario or 'The owner must provide the acceptance evidence above before the parent release gate can be closed. Product acceptance is recorded independently from engineering completion.'),
            '## Test provenance\nAll employees and historical events here are fictional. Jira creation and comment timestamps show the actual seeding time. Historical dates are narrative event dates, not backdated Jira changes. Fictional ownership is described here because no matching test assignee account is assumed.'
        ])
        item['comments']=[dict(fictional_author=owner,event_date='2026-11-06',body=f"Fictional project history, November 6: {owner} accepted ownership of this scope. Problem under review: {item['problem']}. Acceptance evidence must cover: {item['acceptance_criteria'][0]}."),dict(fictional_author=owner,event_date=AS_OF,body=f"Fictional status review, November 16: {item['business_state']}. "+('Acceptance completed on '+item['fictional_completed_date']+'. ' if item['business_state']=='Done' else 'Target remains '+item['due_date']+'. ')+(scenario if scenario else 'The next review will inspect the recorded acceptance checks before changing the parent gate.')+' Posted by the dataset operator on behalf of this fictional narrative; not an actual employee comment.')]
        if item['seed_id']=='harbor-ownership': item['comments'][0]['body']='Fictional history, November 10: Omar Haddad is still listed as the partner authentication implementation owner in the original staffing note. Handover is proposed, not effective yet.'
        if item['seed_id']=='harbor-ownership': item['comments'][1]['body']='Fictional decision effective November 12: Maya Chen transfers HARBOR authentication implementation to Leo Martinez. Omar Haddad retains shared identity ownership and consultation. Aisha Rahman accepts the product handoff. This supersedes the November 10 staffing note.'
        if item['seed_id']=='atlas-tenant-leak': item['comments'][0]['body']='Fictional security review November 10: refresh token replay crossed two internal test tenants. Noah Kim opened the release gate. The finding is internal and contains no real customer records.'
        if item['seed_id']=='atlas-tenant-leak': item['comments'][1]['body']='Fictional resolution November 13: tenant mismatch now returns 403 and replay regressions pass. ATLAS refresh replay remediation is complete. The separate claims v2 implementation and BEACON warehouse partition fixes remain open; this is not a portfolio security clearance.'
        item['publication']=read('jira/remote-map.json',{}).get(item['seed_id'],dict(status='local_only',key=None,id=None,url=None))
        save('jira/issues/'+item['seed_id']+'.json',item)
        save('jira/issues/'+item['seed_id']+'.md','# '+item['summary']+'\n\n'+item['description']+'\n\n## Narrative comments\n\n'+'\n\n'.join(c['body'] for c in item['comments'])+'\n')
    save('jira/seed-issues.json',issues)
    save('jira/relationships.json',[dict(inward_seed=a,outward_seed=b,type=t) for a,b,t in LINKS])
    return issues

# key, group, title, fictional owner, effective date, lifecycle, focused material
PAGES = [
 ('company-overview','company','AsterBridge Labs company and teams','maya','2026-11-16','current','AsterBridge Labs builds enterprise SaaS products for customer administration, analytics, and partner connectivity. The 18 named employees form the delivery cohort used by this test organization. They are not the entire headcount of the mid sized fictional company. Engineering owns shared identity and portal delivery. Product owns scope and business release authorization. Security approves access boundaries and privacy standards. DevOps owns delivery reliability. Data owns pipelines and metric semantics. Customer Success owns pilot communication and training. Shared services are the identity service, event envelope, tenant boundary, audit pipeline, and release process.'),
 ('portfolio','company','November portfolio review and dependencies','maya','2026-11-16','current','The portfolio review reserves Omar for the shared identity contract before additional partner implementation. Maya remains delivery accountable across the three projects. The critical path runs from identity claims to ATLAS application events and then BEACON reconciliation. HARBOR delivery infrastructure is a distinct workstream whose completed checks cannot substitute for authentication or commercial acceptance. Elena owns the tradeoff if the revised ATLAS target slips. A decision is needed on November 19 if identity acceptance remains incomplete.'),
 ('onboarding','company','Delivery team onboarding and source navigation','chloe','2026-11-16','current','New joiners first read the company overview, then their project roadmap, and then the current architecture decision. Jira is the operational work record. Confluence records approved policies and explanations. Business status files preserve dated management views. Ask for source evidence when a status summary uses words such as complete, approved, or ready. A November 6 report is not evidence of the November 16 state. Do not merge people or projects solely because their names appear in different tools.'),
 ('engineering-process','engineering','Engineering workflow and release evidence','maya','2026-11-16','current','Stories express user outcomes, tasks capture bounded operational work, bugs describe observed failures, epics organize delivery, and subtasks collect narrowly scoped acceptance evidence. Completion requires a result for each acceptance check and named owner review. A blocked work item may remain in a supported Jira In Progress status with the abl-blocked label and an explicit dependency. Reviews distinguish this representation from a native Blocked workflow status. A release needs technical, security, operational, and business evidence separately.'),
 ('adr-identity','engineering','ADR 007 tenant bound identity contract','sofia','2026-11-11','approved','Decision: require tenant_id and a product specific audience for all product access tokens. Tenant context comes from verified credentials, never from a user supplied header alone. The refresh replay finding showed that permissive consumers could mistake possession of a token for authorization to another tenant. We rejected an optional tenant field because its fallback behavior varied across products. The decision supersedes the November 3 draft. Omar owns the contract, Leo owns the HARBOR consumer, and Noah owns negative security tests. Approval of this architecture does not establish deployment or test completion.'),
 ('identity-draft','engineering','Identity contract discussion from November 3','omar','2026-11-03','superseded','Historical proposal: allow the tenant claim to be optional and use a broad shared audience while pilot services are small. The proposal aimed to reduce early consumer implementation work. It was not the final security approval. Sofia rejected the fallback after the refresh replay finding. ADR 007 dated November 11 supersedes this document. Preserve the draft to answer what changed, but never treat its statements as current implementation requirements.'),
 ('security-standard','engineering','Access control and partner signing standard','sofia','2026-11-11','approved','Server authorization checks a verified tenant boundary and product audience before evaluating the capability matrix. Analyst access never authorizes user administration. Access token validation, reset token expiry, and webhook signing key rotation are separate controls. Partner signing keys rotate every 30 days with a maximum 24 hour overlap. Reset links expire after 15 minutes and are single use. Logs must redact access tokens and signing secrets. Security exception approval belongs to Sofia and must include scope and expiry; no exception is granted by this page.'),
 ('events-api','engineering','Application event API contract version 2','grace','2026-11-12','approved','Envelope fields are event_id, tenant_id, schema_version, occurred_at in UTC, event_type, consent_revision, and a nonidentifying correlation_id. Event IDs are unique within tenant scope. Consumers quarantine unsupported schema versions and expose their processing watermark. Routine events exclude raw email addresses. Consent withdrawal suppresses nonessential events. Deletion tombstones must prevent later replay from resurrecting removed subjects. The specification is approved, but the ATLAS publishing endpoint is still unfinished. BEACON must validate the real endpoint rather than infer availability from this page.'),
 ('retention-policy','engineering','Approved analytics and audit retention policy','yara','2026-11-12','approved','Raw analytics events expire after 30 days. Aggregated usage data is retained for 13 months subject to deletion obligations. Security audit entries use a separate 90 day retention window. The analytics raw event draft from November 5 is superseded. Data engineers must configure expiry jobs and test deletion and replay behavior. A longer aggregate retention period does not authorize storing raw identifying events for the same duration. Policy owner Yara reviews exceptions with Sofia.'),
 ('retention-draft','engineering','Analytics retention proposal from November 5','grace','2026-11-05','superseded','This historical working proposal requested 90 days of raw analytics events for backfill convenience. Privacy review did not approve that window. The approved November 12 policy reduces raw retention to 30 days and permits 13 months for aggregates. Keep this document for decision history. The number 90 also appears in the security audit policy, which concerns a different record class. Matching numbers across those contexts does not establish an actual policy conflict.'),
 ('incident-process','engineering','Incident escalation and operational ownership','ben','2026-11-16','current','Classify the failing boundary before paging. Availability or webhook delivery incidents go to Ben. Data correctness incidents go to Grace. Partner authentication implementation questions go to Leo with Omar consulted on shared identity. Commercial launch approval goes to Aisha and Elena. Incident commander records a timeline, affected test tenants, mitigation, rollback condition, and follow up actions. Closing an incident does not automatically close unrelated release dependencies. A missed source search hit is not evidence that the source record was deleted.'),
 ('handover','engineering','Partner authentication ownership handover','maya','2026-11-12','approved','Effective November 12, Leo becomes HARBOR authentication implementation owner. Omar retains identity service ownership and is consulted on claims v2. Aisha owns partner product scope and acceptance coordination. Maya remains overall engineering delivery accountable. The earlier staffing note naming Omar as both contract and consumer owner is historical. Leo must update SDK examples, tenant scoped partner mapping, and consumer tests. The handover changes accountability, not the security contract or the remaining blockers.'),
 ('atlas-overview','projects/atlas','ATLAS customer portal scope and ownership','daniel','2026-11-16','current','ATLAS beta provides customer account administration, invitations, profile preferences, and role based access for owner, admin, and analyst. Daniel owns product acceptance, Omar the identity implementation, Priya the frontend, and Maya delivery accountability. Billing administration is excluded from this beta and remains a later decision. English and Arabic journeys require keyboard and screen reader coverage. Pilot training should assign analyst privileges to reporting users rather than granting owner access as a convenience.'),
 ('atlas-release','projects/atlas','ATLAS revised beta release plan','maya','2026-11-16','current','The release board revised the beta date because identity claims v2 and consent filtered event publishing remain incomplete. Daniel accepts customer scope, Sofia accepts security evidence, Ben accepts operational rehearsal, and Elena authorizes business launch. On November 19 Maya reviews the remaining identity work and updates the release risk if its acceptance slips. A finished portal screen is insufficient for launch. Pilot communications must explain the revised date without implying a contractual availability commitment.'),
 ('atlas-api','projects/atlas','ATLAS account administration API and RBAC','omar','2026-11-12','approved','Account routes use verified tenant context on every request. Invitation creation is permitted only for approved owner or admin capabilities, binds the invitation to a tenant, and expires after 48 hours. Membership removal invalidates role caches within 30 seconds. Analyst cannot create users or change roles. Export routes must neutralize formula shaped values before producing CSV. Password reset responses avoid user enumeration and links are single use. Denial logs retain safe correlation IDs without credentials.'),
 ('atlas-runbook','projects/atlas','ATLAS beta rollout and rollback runbook','ben','2026-11-16','current','Before rollout inspect identity and event acceptance, smoke test account routes, confirm on call coverage, and obtain release approvals. Deploy to staging before pilot exposure. Stop rollout if tenant mismatch checks fail or event suppression is unverified. Rollback target is ten minutes to the prior compatible application; token contract compatibility is checked separately from database compatibility. Preserve audit records and do not erase evidence to make the health view green. Record observed recovery duration and test scope.'),
 ('beacon-overview','projects/beacon','BEACON analytics platform scope and ownership','grace','2026-11-16','current','BEACON turns approved application events into customer adoption and activation reports. Grace owns pipelines, Tomas dashboard semantics, Fatima data quality, Yara privacy review, and Maya delivery. Chloe validates whether the metrics answer Customer Success questions. Event processing and query authorization both enforce tenant boundaries. A complete chart cannot prove complete input coverage. The reporting pilot is limited to approved test tenants and is not a production wide analytics rollout.'),
 ('beacon-roadmap','projects/beacon','BEACON revised reporting pilot roadmap','grace','2026-11-16','current','Pipeline integration comes before reconciliation, cohort verification, and pilot business approval. The team reserves two days for reconciliation after ATLAS events acceptance. This shifts the reporting pilot out of November. Tomas can continue dashboard presentation work against fixtures, but fixture completion cannot clear the live data gate. The release board must reconsider scope if upstream delivery misses its revised target. Customer briefings and dependency trackers must use the latest target and identify it as conditional.'),
 ('metrics','projects/beacon','Analytics metric definitions and freshness','tomas','2026-11-10','approved','An active user performs an eligible action within a seven day UTC window; a login alone is not activation. Activation uses the first qualifying event per tenant and subject under the approved metric version. Service accounts and opted out events are excluded. UTC boundaries determine aggregation, while the interface may show Asia Riyadh dates for the reader. Labels distinguish a genuine zero from missing or partially processed input. The latest successful source watermark describes freshness, not the time a viewer opened the dashboard.'),
 ('beacon-runbook','projects/beacon','BEACON ingestion reconciliation runbook','fatima','2026-11-16','current','Check the last successful event watermark and partition completeness before interpreting counts. Require zero cross tenant rows. Investigate a source versus warehouse count difference greater than 0.5 percent. Recompute a seven day window for late arrivals using original occurrence time. Deduplicate on tenant and event_id, preserving intentional corrected versions. A replay after subject deletion must not resurrect aggregates. Grace owns correctness escalation, and Ben owns availability recovery.'),
 ('incident-replay','projects/beacon','November 9 activation replay postmortem','grace','2026-11-13','closed','An internal test replay on November 9 duplicated activation events and inflated pilot metrics. Fatima traced the failure to missing tenant scoped event deduplication. The mitigation paused the affected test partition while counts were reconciled. Dedupe remediation completed November 12 and the follow up closed November 13. No real customer incident or external loss is asserted. Follow up adds replay fixtures and safe source watermarks. The unresolved ATLAS events endpoint is a separate dependency with a different status.'),
 ('harbor-overview','projects/harbor','HARBOR partner pilot scope and ownership','aisha','2026-11-16','current','HARBOR supports partner sandbox onboarding, tenant scoped API integration, and signed webhook delivery. Leo owns partner implementation following the November 12 handover. Aisha owns partner scope and commercial coordination. Ben owns operational readiness, Sofia security approval, Ethan sandbox feedback, and Elena final Product launch authorization. The first pilot excludes regional expansion. Sharing a token service with ATLAS does not transfer product ownership or eliminate consumer acceptance.'),
 ('harbor-release','projects/harbor','HARBOR pilot technical and business release gates','aisha','2026-11-16','current','There are three distinct gates: webhook delivery technical acceptance, authentication security acceptance, and business launch authorization. Delivery checks passed November 13. The other gates remain open. The partner data agreement requires an actual signed reference, and Elena must record Product approval. No signature or legal approval is fabricated in this dataset. The pilot target remains conditional on November 24. A delivery component marked Done does not mean the complete partner pilot is ready.'),
 ('partner-runbook','projects/harbor','Partner delivery recovery and escalation runbook','ben','2026-11-13','approved','Webhook requests use HMAC SHA256 with a key ID and a five minute replay window. The delivery ID supports deduplication and reviewed dead letter replay. Retry at most eight attempts with bounded exponential delay and respect Retry After within that cap. Connection timeout is three seconds and total request timeout ten seconds. Pause only the affected tenant during recovery. Signing secrets never appear in logs. Escalate delivery availability to Ben, authentication implementation to Leo, and agreement questions to Aisha.'),
 ('partner-note','projects/harbor','Partner kickoff signing key note from November 6','ethan','2026-11-06','superseded','The partner kickoff note proposed 90 day webhook signing key rotation to reduce partner operations. This was an unapproved discussion note. Sofia approved 30 day rotation with a maximum 24 hour overlap in the November 11 security standard. Preserve this note to test conflict and freshness handling. It does not override the approved standard, and it says nothing about the lifetime of access tokens. Ethan owns partner communication, not security exception approval.'),
]

