def build_pages_and_docs(issues):
    pages=[]
    for id,group,title,owner,effective,lifecycle,body in PAGES:
        fset=facts_for('pages',id)
        refs=list(dict.fromkeys(i for f in fset for i in f['issues']))
        if not refs: refs=['atlas-readiness','beacon-readiness','harbor-checklist']
        context='\n\n'.join(f['answer'] for f in fset)
        text=f'# {title}\n\nOwner: {PEOPLE[owner]}\n\nEffective date: {effective}\n\nLifecycle: {lifecycle}\n\nAsterBridge Labs fictional test organization.\n\n## Purpose and decision\n\n{body}\n\n'
        if id in PAGE_ADDENDA:text+='## Responsibilities and working procedure\n\n'+PAGE_ADDENDA[id]+'\n\n'
        if context:text+='## Recorded project context\n\n'+context+'\n\n'
        text+='## Evidence and accountability\n\n'+references(refs)+'.\n\nThe linked work records retain operational status and acceptance criteria. This page records the dated decision and its scope. A policy marked approved is not evidence that every implementation task is Done. The named document owner maintains the explanation; the issue owner supplies implementation evidence.\n\n'
        text+='## Review and change handling\n\nReview this record when the linked scope, owner, or release gate changes. Keep the earlier effective date visible when answering historical questions. A superseded proposal remains useful for explaining a change but cannot authorize a current implementation. Where the evidence does not contain a signature, approval, deployment result, or production measurement, report that item as missing. Links do not grant access to restricted material.\n\n'
        if lifecycle=='superseded':text+='## Historical use\n\nThis is retained history with an explicit superseded status. It must not be silently rewritten into the current decision. Compare it with the approved current policy before describing a conflict.\n'
        path=f'confluence/{group}/{id}.md';save(path,text)
        pages.append(dict(seed_id=id,title='AsterBridge Labs — '+title,space_key='COMPANY' if group=='company' else 'ENGINEERING' if group=='engineering' else group.split('/')[-1].upper(),owner=owner,effective_date=effective,lifecycle=lifecycle,path=path,body=text,issue_seeds=refs,intended_access='security-reviewers' if id=='security-standard' else 'all-staff',publication=read('confluence/remote-map.json',{}).get(id,{'status':'local_only','id':None,'url':None})))
    save('confluence/pages.json',pages)
    docs=[]
    for id,folder,title,owner,effective,fids,fmt in DOCS:
        relevant=[f for f in FACTS if f['id'] in fids]
        refs=list(dict.fromkeys(i for f in relevant for i in f['issues']))
        sections=[]
        if id=='weekly-old':
            intro='As of November 6, the planning targets are ATLAS November 20, BEACON November 30, and HARBOR November 24. These are preliminary targets before the November 11 identity decision. Omar Haddad currently owns partner authentication implementation.'
            sections=[('Planning view on November 6',intro),('Open assumptions','The plan assumes that the shared identity contract will be accepted without additional tenant boundary work. No final security clearance or partner commercial approval is recorded. The team will revisit the dates after Security review.'),('Actions','Maya will review platform capacity. Grace will confirm event readiness. Aisha will collect partner agreement requirements. This historical report is retained and superseded by the November 16 weekly report for current status.')]
            refs=['atlas-readiness','beacon-readiness','harbor-ownership']
        else:
            intro=relevant[0]['answer'] if relevant else 'This briefing records the shared enterprise pilot delivery position.'
            sections=[('Delivery position',intro)]+[(f['id'].replace('-',' ').capitalize(),f['answer']) for f in relevant[1:]]
            action={
             'company-brief':'Maya will review platform capacity on November 19. Elena will review Product approvals separately from technical readiness. Chloe will keep pilot communication aligned with the revised targets.',
             'weekly-current':'Omar must provide identity claims acceptance by November 18. Grace then needs final event inputs to verify reconciliation. Aisha must secure the partner agreement before requesting Elena launch approval.',
             'atlas-status':'Daniel will accept customer scope after identity and events gates clear. Priya continues Arabic keyboard and accessibility checks. Ben rehearses the revised rollout on November 26.',
             'beacon-status':'Grace owns event integration and Fatima owns reconciliation. Tomas can finish presentation against fixtures, but a fixture result does not close the upstream data gate. Chloe updates the pilot briefing to December 4.',
             'harbor-status':'Leo must finish authentication consumer acceptance. Aisha owns the unsigned agreement action. Elena has not recorded a final Product launch decision. Keep webhook delivery acceptance visible as a scoped achievement.',
             'handover-minutes':'Attendees were Maya Chen, Omar Haddad, Leo Martinez, Aisha Rahman, and Sofia Alvarez. Maya confirmed the ownership change effective November 12. Omar remains consulted on the identity contract. Leo will update SDK examples and consumer tests.',
             'release-readiness':'Ben accepted webhook delivery checks only. He did not authorize the full partner pilot. Release owners must record technical, security, operational, and business evidence individually before marking the full release ready.',
             'product-requirements':'Customer owners manage membership, analysts consume reports, and partners receive only necessary payload fields. Billing administration and regional partner expansion remain outside this pilot. No signed customer commitment or booked revenue is asserted.',
             'security-assessment':'This assessment is intended for the fictional security review group. It uses internal test tenants only. No real credentials, customer identities, or exploit payloads are included. Restriction intent is not proof that a remote ACL is configured.',
             'customer-feedback':'Fictional pilot feedback: one analyst asked whether an empty chart meant zero adoption; two onboarding reviewers requested clearer role explanations; partner sandbox testers requested current authentication examples. These qualitative test comments do not represent a survey or a measured customer population.',
             'operations-report':'The webhook retry cap is eight attempts. Connection timeout is three seconds and total request timeout ten seconds. Only reviewed tenant scoped dead letter replay is permitted. The prior replay incident is closed, while identity and event dependencies remain open.'
            }.get(id,'Owners update the linked work records when a prerequisite changes. This dated snapshot must not replace current operational status.')
            sections.append(('Actions and decisions',action))
        business=[text for doc_id,text in BUSINESS_EVIDENCE.values() if doc_id==id]
        if business:sections.append(('Business actions and impact',' '.join(business)))
        if id=='operations-report':sections.append(('Reconciliation threshold requiring review','The November 14 Operations meeting note calls a 1.0 percent source to warehouse count variance threshold agreed for the BEACON pilot. No Data or Security approval is attached. The current Data runbook and Jira acceptance criteria instead require investigation above 0.5 percent. Grace and Ben must reconcile these records before the pilot; this report does not silently amend the runbook.'))
        sections.append(('Supporting work records',references(refs)))
        source=f'# {title}\n\nAsterBridge Labs\n\nAuthor: {PEOPLE[owner]}\n\nReport date: {effective}\n\n'+'\n\n'.join('## '+h+'\n\n'+b for h,b in sections)+'\n'
        source_path=f'onedrive/editable-sources/{id}.md';save(source_path,source)
        docs.append(dict(seed_id=id,title=title,folder=folder,owner=owner,report_date=effective,format=fmt,sections=sections,path=f'onedrive/AsterBridge Labs/{folder}/{id}.{fmt}',editable_source=source_path,issue_seeds=refs,fact_ids=fids,intended_access='security-reviewers' if id in ['security-assessment','risk-register'] else 'all-staff',publication={'status':'local_only','id':None,'url':None}))
    save('onedrive/documents.json',docs)
    return pages,docs

def build_org():
    save('organization/employees.json',[dict(id=i,name=n,team=t,role=r,responsibilities=d,fictional=True,jira_account_id=None) for i,n,t,r,d in EMPLOYEES])
    save('organization/teams.json',[dict(name=t,members=[i for i,n,team,r,d in EMPLOYEES if team==t],lead=next(i for i,n,team,r,d in EMPLOYEES if team==t)) for t in dict.fromkeys(x[2] for x in EMPLOYEES)])
    save('organization/projects.json',PROJECTS)
    save('organization/facts.json',FACTS)
    save('organization/company-profile.md','# AsterBridge Labs\n\nA fictional mid sized enterprise SaaS company. This dataset describes an 18 person cross functional delivery cohort, with Engineering, Product, Security, DevOps, Data, and Customer Success teams. It is not a complete employee census.\n\nATLAS supplies shared tenant identity and application events. BEACON consumes approved events and supplies adoption insights. HARBOR uses the shared identity contract and provides signed partner webhooks. Maya Chen is engineering delivery accountable, Elena Petrova is Product Director, and Sofia Alvarez is Security Lead.\n\nScenario clock: November 16, 2026. Historical event dates are fictional narrative dates. Actual source creation and update times are recorded separately in remote snapshots.\n')

def main():
    build_org();issues=build_issues();pages,docs=build_pages_and_docs(issues)
    save('organization/scenario-clock.json',dict(as_of=AS_OF,timezone='Asia/Riyadh',historical_events_are_fictional=True,remote_timestamps_are_actual=True))
    save('jira/jira-manifest.json',dict(dataset=DATASET,site=SITE,cloud_id='ccf2f991-7acb-4c59-8be2-baf48d7b7eaf',planned_issues=len(issues),published=sum(bool(i['publication'].get('key')) for i in issues),remote_map='jira/remote-map.json',full_snapshots='jira/snapshots/',native_assignees='Unassigned unless a verified fictional test account is explicitly mapped',blocked_representation='Use native Blocked when available, otherwise In Progress plus abl-blocked label; business_state remains explicit',releases_and_sprints='Planning names in descriptions; native versions and sprints only if actually created and confirmed'))
    save('source-manifest.json',dict(dataset=DATASET,as_of=AS_OF,synthetic=True,issues=[dict(seed_id=i['seed_id'],path='jira/issues/'+i['seed_id']+'.json',publication=i['publication']) for i in issues],pages=[{k:p[k] for k in ['seed_id','path','publication','issue_seeds','intended_access']} for p in pages],documents=[{k:d[k] for k in ['seed_id','path','editable_source','publication','issue_seeds','intended_access']} for d in docs],relationships='jira/relationships.json',facts='organization/facts.json',limitation='Dataset preparation does not establish Linkmind connector or AI acceptance. Intended permission groups require actual ACL setup and distinct authorized principals before security acceptance.'))
    print(json.dumps(dict(issues=len(issues),pages=len(pages),documents=len(docs))))

if __name__=='__main__':main()
